/**
 * Shared filesystem path helpers for DeepSeek Harness user data.
 *
 * @module @deepseek-ai/dsh-home-paths
 */

import { opendir, realpath } from 'node:fs/promises'
import { homedir } from 'node:os'
import { basename, dirname, join, resolve } from 'node:path'
export { resolvePortablePath, encodePortablePath, rememberPortableWorkspace, assertPortableWorkspaceIdentity } from './portable.ts'

/** Directory name for the default DeepSeek Harness home under the OS home. */
export const DSH_HOME_DIR_NAME = '.dsh'

/** Stable user-facing display form for the default DeepSeek Harness home. */
export const DEFAULT_DSH_HOME_DISPLAY = `~/${DSH_HOME_DIR_NAME}`

/** Environment variable that overrides the default DeepSeek Harness home. */
export const DSH_HOME_ENV = 'DSH_HOME'

/** Directory name for the default shared agent configuration root under the OS home. */
export const AGENTS_HOME_DIR_NAME = '.agents'

/** Stable user-facing display form for the default shared agent configuration root. */
export const DEFAULT_AGENTS_HOME_DISPLAY = `~/${AGENTS_HOME_DIR_NAME}`

/** Environment variable that overrides the default shared agent configuration root. */
export const AGENTS_HOME_ENV = 'DSH_AGENTS_HOME'

/**
 * Give a native filesystem watcher one canonical spelling of a path, even
 * when its final components do not exist yet. The deepest existing ancestor
 * is resolved through {@link realpath}; when a suffix is missing, that
 * ancestor is also proved to be an enumerable directory before the suffix is
 * restored. This prevents Windows from treating a regular-file ancestor as
 * ordinary absence, and prevents short-name aliases from being mixed with
 * long paths emitted by the native watcher backend.
 * @param path - Watch target or root, resolved against the current directory.
 * @returns the target with its existing ancestor canonicalized.
 * @throws when ancestor traversal encounters an error other than absence, or
 * the existing ancestor of a missing suffix is not an enumerable directory.
 */
export async function canonicalizeWatchPath(path: string): Promise<string> {
  let current = resolve(path)
  const missing: string[] = []
  while (true) {
    try {
      const canonical = await realpath(current)
      if (missing.length > 0) {
        // A Windows file-as-parent probe reports ENOENT. Opening the resolved
        // ancestor preserves the cross-platform directory requirement.
        const directory = await opendir(canonical)
        await directory.close()
      }
      return join(canonical, ...missing.reverse())
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error
      const parent = dirname(current)
      /* v8 ignore next -- a filesystem root exists, so traversal resolves before this guard */
      if (parent === current) throw error
      missing.push(basename(current))
      current = parent
    }
  }
}

/**
 * Resolve the default DeepSeek Harness home using Node's platform path rules.
 * @returns the absolute default harness home path.
 */
export function defaultDshHome(): string {
  return join(homedir(), DSH_HOME_DIR_NAME)
}

/**
 * Resolve the default shared agent configuration root using Node's platform path rules.
 * @returns the absolute default shared agent configuration root.
 */
export function defaultAgentsHome(): string {
  return join(homedir(), AGENTS_HOME_DIR_NAME)
}

/**
 * Expand supported tilde prefixes against the operating-system home.
 * @param path - configured path that may begin with `~`, `~/`, or `~\`.
 * @returns the expanded path, or the original value when no supported prefix is present.
 */
export function expandHomePath(path: string): string {
  if (path === '~') return homedir()
  if (path.startsWith('~/') || path.startsWith('~\\')) return join(homedir(), path.slice(2))
  return path
}

/**
 * Resolve one user-data root from an explicit path, an environment override, and a default.
 * @param configured - explicit path, which has highest precedence.
 * @param env - environment mapping to read.
 * @param envName - environment variable that overrides the default.
 * @param fallback - default root, used when neither the explicit path nor the environment provides one.
 * @returns the normalized absolute root.
 */
function resolveRoot(
  configured: string | undefined,
  env: Record<string, string | undefined>,
  envName: string,
  fallback: () => string,
): string {
  const fromEnv = env[envName]
  const selected = configured ?? (fromEnv !== undefined && fromEnv.trim().length > 0 ? fromEnv : fallback())
  return resolve(expandHomePath(selected))
}

/**
 * Label one resolved user-data root symbolically for user-facing display.
 * @param resolvedRoot - absolute path returned by the matching resolver.
 * @param defaultRoot - absolute default root whose symbolic label applies to a match.
 * @param defaultLabel - symbolic label for the default root.
 * @param envName - environment variable name that labels any other root.
 * @returns the symbolic label.
 */
function rootDisplay(resolvedRoot: string, defaultRoot: string, defaultLabel: string, envName: string): string {
  return resolvedRoot === resolve(defaultRoot) ? defaultLabel : `$${envName}`
}

/**
 * Resolve the single-root DeepSeek Harness home.
 *
 * Precedence, highest first: an explicit configured path, `$DSH_HOME`, then
 * `~/.dsh`. The harness keeps all user data under one root. An empty or
 * whitespace-only `$DSH_HOME` is treated as unset, so a blank override never
 * resolves the home to the current working directory.
 * @param configured - explicit harness-home override, which has highest precedence.
 * @param env - environment mapping used to read `DSH_HOME`.
 * @returns the normalized absolute harness home path.
 */
export function resolveDshHome(configured?: string, env: Record<string, string | undefined> = process.env): string {
  return resolveRoot(configured, env, DSH_HOME_ENV, defaultDshHome)
}

/**
 * Resolve the shared agent configuration root.
 *
 * Precedence, highest first: an explicit configured path, `$DSH_AGENTS_HOME`,
 * then `~/.agents`. The root holds configuration shared with other agent tools,
 * so it stays independent of the DeepSeek Harness home. An empty or
 * whitespace-only `$DSH_AGENTS_HOME` is treated as unset, so a blank override
 * never resolves the root to the current working directory.
 * @param configured - explicit shared-root override, which has highest precedence.
 * @param env - environment mapping used to read `DSH_AGENTS_HOME`.
 * @returns the normalized absolute shared agent configuration root.
 */
export function resolveAgentsHome(configured?: string, env: Record<string, string | undefined> = process.env): string {
  return resolveRoot(configured, env, AGENTS_HOME_ENV, defaultAgentsHome)
}

/**
 * Join path segments onto the resolved DeepSeek Harness home.
 * @param segments - path segments appended to the Harness home; an empty list returns the home itself.
 * @returns the normalized absolute joined path.
 */
export function dshHomePath(...segments: string[]): string {
  return join(resolveDshHome(), ...segments)
}

/**
 * Join path segments onto the resolved Harness home's `cache` directory without creating it; no arguments returns the directory itself.
 * @param optionsOrSegment - explicit home override, or the first path segment; omission uses the default home resolution.
 * @param segments - additional path segments after the first child, if any.
 * @returns the normalized absolute cache path.
 */
export function dshCachePath(optionsOrSegment: { dshHome?: string } | string = {}, ...segments: string[]): string {
  if (typeof optionsOrSegment === 'string') return dshHomePath('cache', optionsOrSegment, ...segments)
  return join(resolveDshHome(optionsOrSegment.dshHome), 'cache', ...segments)
}

/**
 * Describe a resolved harness home symbolically for user-facing display.
 *
 * It never returns an absolute machine path: the default home is labelled
 * `~/.dsh`, and any configured home is labelled `$DSH_HOME`.
 * @param resolvedHome - the absolute path returned by {@link resolveDshHome}.
 * @returns `~/.dsh` for the default home, otherwise `$DSH_HOME`.
 */
export function dshHomeDisplay(resolvedHome: string): string {
  return rootDisplay(resolvedHome, defaultDshHome(), DEFAULT_DSH_HOME_DISPLAY, DSH_HOME_ENV)
}

/**
 * Describe a resolved shared agent configuration root symbolically for user-facing display.
 *
 * It never returns an absolute machine path: the default root is labelled
 * `~/.agents`, and any configured root is labelled `$DSH_AGENTS_HOME`.
 * @param resolvedHome - the absolute path returned by {@link resolveAgentsHome}.
 * @returns `~/.agents` for the default root, otherwise `$DSH_AGENTS_HOME`.
 */
export function agentsHomeDisplay(resolvedHome: string): string {
  return rootDisplay(resolvedHome, defaultAgentsHome(), DEFAULT_AGENTS_HOME_DISPLAY, AGENTS_HOME_ENV)
}

/** Portable workspace references and runtime-only relocation of historical paths. */
import { createHash, randomUUID } from 'node:crypto'
import { execFileSync } from 'node:child_process'
import { closeSync, fsyncSync, mkdirSync, openSync, readFileSync, readdirSync, renameSync, rmSync, writeFileSync } from 'node:fs'
import { dirname, isAbsolute, join, relative, resolve, sep } from 'node:path'

const PREFIX = 'dsh-portable:/'

function within(root: string, path: string): boolean {
  const rest = relative(root, path)
  return rest === '' || (rest !== '..' && !rest.startsWith(`..${sep}`) && !isAbsolute(rest))
}

function portableRoot(): string | undefined {
  const root = process.env.DSH_PORTABLE_ROOT
  return root === undefined ? undefined : resolve(root)
}

/**
 * Resolve a portable reference or a historical absolute path without rewriting Session logs.
 * @param path - Stored workspace reference or path from an immutable Session header.
 * @returns The current absolute path; ordinary installations retain the supplied path.
 */
function resolveBase(path: string): string {
  const root = portableRoot()
  if (root === undefined) return path
  if (path.startsWith(PREFIX)) {
    const rest = decodeURIComponent(path.slice(PREFIX.length))
    const decoded = resolve(root, rest)
    if (!within(root, decoded)) throw new Error('portable workspace reference escapes its package')
    return decoded
  }
  if (!isAbsolute(path) || within(root, path)) return path
  const state: unknown = JSON.parse(readFileSync(join(root, 'data', 'portable-state.json'), 'utf8'))
  if (typeof state !== 'object' || state === null || !('roots' in state) || !Array.isArray(state.roots)
    || state.roots.some(value => typeof value !== 'string')) throw new Error('portable path history is invalid')
  const roots = (state.roots as string[]).toSorted((a, b) => b.length - a.length)
  for (const previous of roots) if (within(previous, path)) return resolve(root, relative(previous, path))
  return path
}

interface WorkspaceLocation {
  format: 1
  originalPath: string
  location: string
  identity?: string
  machine?: string
}

function locations(root: string): WorkspaceLocation[] {
  let names: string[]
  try { names = readdirSync(join(root, 'data', 'workspace-identities')) }
  catch (error) { if ((error as NodeJS.ErrnoException).code === 'ENOENT') return []; throw error }
  return names.filter(name => /^[a-f0-9]{64}\.json$/u.test(name)).map((name) => {
    const raw: unknown = JSON.parse(readFileSync(join(root, 'data', 'workspace-identities', name), 'utf8'))
    if (typeof raw !== 'object' || raw === null || !('format' in raw) || raw.format !== 1) throw new Error('portable workspace location record is invalid')
    const record = raw as Record<string, unknown>
    const original = record['originalPath'] ?? record['path']
    const location = record['location'] ?? record['path']
    if (typeof original !== 'string' || typeof location !== 'string' || (record['identity'] !== undefined && typeof record['identity'] !== 'string')
      || (record['machine'] !== undefined && typeof record['machine'] !== 'string')) {
      throw new Error('portable workspace location record is invalid')
    }
    return { format: 1, originalPath: original, location,
      ...(typeof record['identity'] === 'string' ? { identity: record['identity'] } : {}),
      ...(typeof record['machine'] === 'string' ? { machine: record['machine'] } : {}) }
  })
}

/**
 * Resolve a recorded path through package moves and explicit user workspace reconnections.
 * @param path - Portable reference or absolute historical path.
 * @returns Its current location without changing any historical Session event.
 */
export function resolvePortablePath(path: string): string {
  const root = portableRoot()
  if (root === undefined) return path
  const current = resolveBase(path)
  if (!isAbsolute(current)) return current
  const records = locations(root)
  for (const record of records) {
    const target = resolveBase(record.location)
    if (record.originalPath !== record.location && within(target, current)) return current
  }
  for (const record of records.toSorted((a, b) => b.originalPath.length - a.originalPath.length)) {
    const original = resolveBase(record.originalPath)
    if (within(original, current)) return resolve(resolveBase(record.location), relative(original, current))
  }
  return current
}

/**
 * Store an internal workspace relative to the package; external paths keep their selected spelling.
 * @param path - Canonical absolute workspace directory.
 * @returns A portable reference inside this package, or the original external path.
 */
export function encodePortablePath(path: string): string {
  const root = portableRoot()
  return root !== undefined && within(root, path)
    ? PREFIX + relative(root, path).split(sep).map(encodeURIComponent).join('/')
    : path
}

function identityFile(root: string, path: string): string {
  const key = createHash('sha256').update((path.startsWith(PREFIX) ? path : resolve(path)).toLowerCase()).digest('hex')
  return join(root, 'data', 'workspace-identities', `${key}.json`)
}

function currentIdentity(path: string): { identity: string; machine: string } {
  const helper = process.env.DSH_PORTABLE_NATIVE_HELPER
  if (helper === undefined) throw new Error('portable workspace identity helper is missing')
  const output = execFileSync(helper, ['identity', path], { encoding: 'utf8', windowsHide: true, maxBuffer: 1024 * 1024 })
  const report: unknown = JSON.parse(output.replace(/^\uFEFF/u, ''))
  if (typeof report !== 'object' || report === null || !('ok' in report) || report.ok !== true
    || !('identity' in report) || typeof report.identity !== 'string'
    || !('machine' in report) || typeof report.machine !== 'string') throw new Error('portable workspace identity is unavailable')
  return { identity: report.identity, machine: report.machine }
}

function currentMachine(): string {
  const helper = process.env.DSH_PORTABLE_NATIVE_HELPER
  if (helper === undefined) throw new Error('portable workspace identity helper is missing')
  const output = execFileSync(helper, ['machine'], { encoding: 'utf8', windowsHide: true, maxBuffer: 1024 * 1024 })
  const report: unknown = JSON.parse(output.replace(/^\uFEFF/u, ''))
  if (typeof report !== 'object' || report === null || !('ok' in report) || report.ok !== true
    || !('machine' in report) || typeof report.machine !== 'string') throw new Error('portable computer identity is unavailable')
  return report.machine
}

/**
 * Remember the directory explicitly selected by the user; choosing it again reconnects it.
 * @param path - Canonical absolute directory selected through Workspace creation.
 */
export function rememberPortableWorkspace(path: string): void {
  const root = portableRoot()
  if (root === undefined) return
  const found = locations(root).find(record => resolveBase(record.originalPath) === path || resolveBase(record.location) === path)
  const location = encodePortablePath(path)
  const originalPath = found?.originalPath ?? location
  const identity = within(root, path) ? undefined : currentIdentity(path)
  const filename = identityFile(root, originalPath)
  mkdirSync(dirname(filename), { recursive: true })
  const temp = `${filename}.${randomUUID()}.tmp`
  let descriptor: number | undefined
  try {
    descriptor = openSync(temp, 'wx', 0o600)
    writeFileSync(descriptor, JSON.stringify({ format: 1, originalPath, location, ...(identity === undefined ? {} : identity) }) + '\n')
    fsyncSync(descriptor)
    closeSync(descriptor)
    descriptor = undefined
    renameSync(temp, filename)
  } finally {
    if (descriptor !== undefined) closeSync(descriptor)
    rmSync(temp, { force: true })
  }
}

/**
 * Refuse an external workspace whose directory identity differs on this computer.
 * @param path - Workspace path, after resolving internal portable references.
 * @throws An ENOENT-class error when the selected original workspace is unavailable.
 */
export function assertPortableWorkspaceIdentity(path: string): void {
  const root = portableRoot()
  if (root === undefined || within(root, path)) return
  const failure = (): Error & { code: string } => Object.assign(
    new Error('原工作区不可用。请在工作区菜单中重新选择原文件夹；聊天记录仍保存在 U 盘。'), { code: 'ENOENT' },
  )
  const stored = locations(root).find(record => resolveBase(record.location) === path)
  if (stored?.identity === undefined || stored.machine === undefined) throw failure()
  if (currentMachine() !== stored.machine) throw failure()
  if (currentIdentity(path).identity !== stored.identity) throw failure()
}

import { afterEach, beforeEach, describe, expect, it } from 'vitest'
import { mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs'
import { join, resolve, relative, isAbsolute } from 'node:path'
import { resolvePortablePath, encodePortablePath, rememberPortableWorkspace, assertPortableWorkspaceIdentity } from '../src/portable.ts'

const fixtures = process.env.DSH_PORTABLE_TEST_ROOT
const helper = process.env.DSH_PORTABLE_TEST_NATIVE_HELPER
let root: string
let prior: NodeJS.ProcessEnv
beforeEach(() => {
  prior = { ...process.env }
  mkdirSync(fixtures as string, { recursive: true })
  root = mkdtempSync(join(fixtures as string, 'paths-'))
  mkdirSync(join(root, 'data'))
  process.env.DSH_PORTABLE_ROOT = root
  process.env.DSH_PORTABLE_NATIVE_HELPER = helper
  writeFileSync(join(root, 'data', 'portable-state.json'), JSON.stringify({ format: 1, roots: [root, 'P:\\旧路径 with spaces'], release: '1.0.0' }))
})
afterEach(() => {
  for (const key of Object.keys(process.env)) if (!(key in prior)) delete process.env[key]
  Object.assign(process.env, prior)
  const rest = relative(resolve(fixtures as string), root)
  if (!rest || rest.startsWith('..') || isAbsolute(rest)) throw new Error('unsafe fixture cleanup')
  rmSync(root, { recursive: true, force: true, maxRetries: 10, retryDelay: 100 })
})

describe.skipIf(process.platform !== 'win32' || !fixtures || !helper)('portable workspace paths', () => {
  it('stores internal paths relatively and resolves historical roots without changing unrelated paths', () => {
    const folder = join(root, 'data', 'workspaces', '中文 project')
    mkdirSync(folder, { recursive: true })
    const encoded = encodePortablePath(folder)
    expect(encoded).toMatch(/^dsh-portable:\//u)
    expect(encoded).not.toContain(root)
    expect(resolvePortablePath(encoded)).toBe(folder)
    expect(resolvePortablePath('P:\\旧路径 with spaces\\data\\workspaces\\中文 project')).toBe(folder)
    expect(resolvePortablePath('P:\\旧路径 with spaces-extra\\file')).toBe('P:\\旧路径 with spaces-extra\\file')
    expect(() => resolvePortablePath('dsh-portable:/..%2F..%2Foutside')).toThrow()
  })

  it('refuses a changed external directory identity and accepts only an explicit reselection', () => {
    const outside = mkdtempSync(join(fixtures as string, 'external-'))
    try {
      rememberPortableWorkspace(outside)
      expect(() => assertPortableWorkspaceIdentity(outside)).not.toThrow()
      const file = join(root, 'data', 'workspace-identities', readdirSync(join(root, 'data', 'workspace-identities'))[0] as string)
      const metadata = JSON.parse(readFileSync(file, 'utf8')) as Record<string, unknown>
      metadata['identity'] = 'another-volume-and-object'
      writeFileSync(file, JSON.stringify(metadata))
      expect(() => assertPortableWorkspaceIdentity(outside)).toThrow(/原工作区不可用/u)
      rememberPortableWorkspace(outside)
      expect(() => assertPortableWorkspaceIdentity(outside)).not.toThrow()
    } finally { rmSync(outside, { recursive: true, force: true, maxRetries: 10, retryDelay: 100 }) }
  })

  it('reconnects historical paths to a selected directory without changing history or remapping twice', () => {
    const old = mkdtempSync(join(fixtures as string, 'old-project-'))
    const selected = join(root, 'data', 'workspaces', 'relocated')
    mkdirSync(selected, { recursive: true })
    try {
      rememberPortableWorkspace(old)
      const folder = join(root, 'data', 'workspace-identities')
      const filename = join(folder, readdirSync(folder)[0] as string)
      const record = JSON.parse(readFileSync(filename, 'utf8')) as Record<string, unknown>
      record['location'] = encodePortablePath(selected)
      writeFileSync(filename, JSON.stringify(record))
      const history = `Read ${join(old, 'report.txt')}`
      expect(resolvePortablePath(old)).toBe(selected)
      expect(resolvePortablePath(join(old, 'report.txt'))).toBe(join(selected, 'report.txt'))
      expect(resolvePortablePath(join(selected, 'report.txt'))).toBe(join(selected, 'report.txt'))
      expect(history).toBe(`Read ${join(old, 'report.txt')}`)
    } finally { rmSync(old, { recursive: true, force: true, maxRetries: 10, retryDelay: 100 }) }
  })

  it('rejects the same path and directory identity when its original computer differs', () => {
    const outside = mkdtempSync(join(fixtures as string, 'same-path-'))
    try {
      rememberPortableWorkspace(outside)
      const file = join(root, 'data', 'workspace-identities', readdirSync(join(root, 'data', 'workspace-identities'))[0] as string)
      const record = JSON.parse(readFileSync(file, 'utf8')) as Record<string, unknown>
      expect(typeof record['machine']).toBe('string')
      record['machine'] = 'another-computer-with-the-same-path-and-object-id'
      writeFileSync(file, JSON.stringify(record))
      expect(() => assertPortableWorkspaceIdentity(outside)).toThrow(/原工作区不可用/u)
      delete record['machine']; writeFileSync(file, JSON.stringify(record))
      expect(() => assertPortableWorkspaceIdentity(outside)).toThrow(/原工作区不可用/u)
      rememberPortableWorkspace(outside)
      expect(() => assertPortableWorkspaceIdentity(outside)).not.toThrow()
      const portable = join(root, 'data', 'workspaces', 'same-name'); mkdirSync(portable, { recursive: true })
      expect(() => assertPortableWorkspaceIdentity(portable)).not.toThrow()
    } finally { rmSync(outside, { recursive: true, force: true, maxRetries: 10, retryDelay: 100 }) }
  })
})

