      return { dispatched: true, verified: false }
    }
    if (method === 'typeText') application.value += params.text
    else if (!['pressKey', 'scroll', 'drag'].includes(method)) refuse('UNSUPPORTED_OPERATION', method)
    return { dispatched: true, verified: false }
  }
  return call
}

