    }
    static IOException MissingFile(string name, string fullPath, Exception error) {
        return new IOException("程序包缺少文件：" + name + "\n完整路径：" + fullPath + "\n解压工具可能跳过了长路径文件。请使用新版完整版重新解压，或在维护中心安装完整版；保留 data。", error);
    }
