                && (ace.AccessMask & 0x1f01ff) == 0x1f01ff && (ace.AceFlags & (AceFlags.ContainerInherit | AceFlags.ObjectInherit)) == (AceFlags.ContainerInherit | AceFlags.ObjectInherit)
