      const temp = filename + '.' + crypto.randomUUID() + '.tmp';
      try {
        fs.writeFileSync(temp, name.endsWith('.json') ? JSON.stringify(next, null, 2) + '\n' : yaml.stringify(next), { flag: 'wx' });
